BASE64 = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
IDX = {c: i for i, c in enumerate(BASE64)}


def decode(mappings):
    """Return list of lines; each line is a list of (gc, si, sl, sc) absolute.  (name omitted)"""
    lines = []
    prev_si = 0
    prev_sl = 0
    prev_sc = 0
    for group in mappings.split(";"):
        gc = 0
        segs = []
        if group:
            for field in group.split(","):
                num = 0
                shift = 0
                for ch in field:
                    digit = IDX[ch]
                    num += (digit & 31) << shift
                    if digit & 32:
                        shift += 5
                    else:
                        break
                neg = num & 1
                v = num >> 1
                if neg:
                    v = -v
                vals = [v]
                # remaining fields
                field = field[len(consumed(field)):] if False else field
                # decode rest of fields
                idx = 0
                for ch in field:
                    pass
                gc += vals[0]
                seg = (gc, None, None, None)
                segs.append(seg)
        lines.append(segs)
    return lines


def _fields(field):
    res = []
    i = 0
    while i < len(field):
        num = 0
        shift = 0
        while True:
            digit = IDX[field[i]]
            num += (digit & 31) << shift
            i += 1
            if digit & 32:
                shift += 5
            else:
                break
        neg = num & 1
        v = num >> 1
        if neg:
            v = -v
        res.append(v)
    return res


def decode2(mappings):
    lines = []
    p_si = p_sl = p_sc = 0
    for group in mappings.split(";"):
        p_gc = 0
        segs = []
        if group:
            for field in group.split(","):
                f = _fields(field)
                p_gc += f[0]
                if len(f) > 1:
                    p_si += f[1]
                if len(f) > 2:
                    p_sl += f[2]
                if len(f) > 3:
                    p_sc += f[3]
                segs.append((p_gc, p_si, p_sl, p_sc))
        lines.append(segs)
    return lines


def encode_vlq(v):
    neg = 0
    if v < 0:
        neg = 1
        v = -v
    num = (v << 1) | neg
    out = []
    while True:
        digit = num & 31
        num >>= 5
        if num > 0:
            digit |= 32
        out.append(BASE64[digit])
        if num == 0:
            break
    return "".join(out)


def encode2(lines):
    """lines: list of lists of (gc, si, sl, sc) absolute (may be None for si/sl/sc means 1-field)"""
    out = []
    p_si = p_sl = p_sc = 0
    for line in lines:
        p_gc = 0
        parts = []
        for (gc, si, sl, sc) in line:
            d = [gc - p_gc]
            p_gc = gc
            if si is not None:
                d.append(si - p_si)
                p_si = si
            if sl is not None:
                d.append(sl - p_sl)
                p_sl = sl
            if sc is not None:
                d.append(sc - p_sc)
                p_sc = sc
            parts.append("".join(encode_vlq(x) for x in d))
        out.append(",".join(parts))
    return ";".join(out)


if __name__ == "__main__":
    m = "AAAA;EACE;EACA,OCFE;EDGF;;;AEDF;EAAS"
    print(decode2(m))

