const fs = require('fs');
const CHARS = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";

function decodeMappings(mappings) {
  const lines = [];
  let line = [];
  let genCol = 0, srcIdx = 0, origLine = 0, origCol = 0, nameIdx = 0;
  let i = 0;
  const s = mappings;
  function decodeVLQ() {
    let shift = 0, val = 0, cont;
    do { const c = CHARS.indexOf(s[i++]); cont = c & 32; val += (c & 31) << shift; shift += 5; } while (cont);
    return (val & 1) ? -(val >> 1) : (val >> 1);
  }
  while (i < s.length) {
    const ch = s[i];
    if (ch === ';') { lines.push(line); line = []; genCol = 0; srcIdx = 0; origLine = 0; origCol = 0; nameIdx = 0; i++; continue; }
    if (ch === ',') { i++; continue; }
    genCol += decodeVLQ();
    const seg = { gc: genCol };
    if (i < s.length && s[i] !== ',' && s[i] !== ';') {
      srcIdx += decodeVLQ(); origLine += decodeVLQ(); origCol += decodeVLQ();
      seg.src = srcIdx; seg.ol = origLine; seg.oc = origCol;
      if (i < s.length && s[i] !== ',' && s[i] !== ';') { nameIdx += decodeVLQ(); seg.n = nameIdx; }
    }
    line.push(seg);
  }
  if (line.length) lines.push(line);
  return lines;
}

const m = JSON.parse(fs.readFileSync(process.argv[2], 'utf8'));
const map = decodeMappings(m.mappings);
// print source index->path
const srcNames = m.sources.map((s, i) => `${i}:${s}`);
console.log('SOURCES:\n' + srcNames.join('\n').replace(/-/g, ''));
console.log('=== mappings near carousel in css (1-based lines shown as generated css lines) ===');
for (let L0 = parseInt(process.argv[4]); L0 <= parseInt(process.argv[5]); L0++) {
  const segs = map[L0] || [];
  const out = segs.map(seg => {
    let sname = seg.src !== undefined ? (m.sources[seg.src] || `src${seg.src}`) : '?';
    return `gc=${seg.gc},src[${seg.src}]="${sname}",ol=${seg.ol},oc=${seg.oc}`;
  }).join('  |  ');
  console.log(`genL ${L0 + 1}: ${out}`);
}

