const CHARS = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";

// Spec-correct decode: at ';' reset only generated column; source/origLine/origCol/name carry across lines.
function decodeMappings(mappings) {
  const lines = [];
  let line = [];
  let genCol = 0, srcIdx = 0, origLine = 0, origCol = 0, nameIdx = 0;
  let i = 0;
  const s = mappings;
  function decodeVLQ() {
    let shift = 0, val = 0, cont;
    do { const c = CHARS.indexOf(s[i++]); cont = c & 32; val += (c & 31) << shift; shift += 5; } while (cont);
    return (val & 1) ? -(val >> 1) : (val >> 1);
  }
  while (i < s.length) {
    const ch = s[i];
    if (ch === ';') { lines.push(line); line = []; genCol = 0; i++; continue; }
    if (ch === ',') { i++; continue; }
    genCol += decodeVLQ();
    const seg = { gc: genCol };
    if (i < s.length && s[i] !== ',' && s[i] !== ';') {
      srcIdx += decodeVLQ(); origLine += decodeVLQ(); origCol += decodeVLQ();
      seg.src = srcIdx; seg.ol = origLine; seg.oc = origCol;
      if (i < s.length && s[i] !== ',' && s[i] !== ';') { nameIdx += decodeVLQ(); seg.n = nameIdx; }
    }
    line.push(seg);
  }
  if (line.length) lines.push(line);
  return lines;
}

module.exports = { decodeMappings };

if (require.main === module) {
  const cmd = process.argv[2];
