const fs = require('fs');
const { decodeMappings } = require('/tmp/opencode/vlq.js');
const { encodeMappings } = require('/tmp/opencode/maptransform.js');

const NEW_SCSS = fs.readFileSync('/testbed/scss/_carousel.scss', 'utf8');

function byteExactSerialize(obj) {
  function esc(s) {
    let out = "";
    for (let i = 0; i < s.length; i++) {
      const c = s.charCodeAt(i);
      if (c === 0x22) out += "\\\"";
      else if (c === 0x5c) out += "\\\\";
      else if (c === 0x08) out += "\\b";
      else if (c === 0x09) out += "\\t";
      else if (c === 0x0a) out += "\\n";
      else if (c === 0x0c) out += "\\f";
      else if (c === 0x0d) out += "\\r";
      else if (c < 0x20) out += "\\u" + c.toString(16).toLowerCase().padStart(4, "0");
      else if (c < 0x80) out += s[i];
      else out += "\\u" + c.toString(16).toLowerCase().padStart(4, "0");
    }
    return "\"" + out + "\"";
  }
  function ser(v) {
    if (v === null) return "null";
    const t = typeof v;
    if (t === "number") return String(v);
    if (t === "boolean") return String(v);
    if (t === "string") return esc(v);
    if (Array.isArray(v)) return "[" + v.map(ser).join(", ") + "]";
    const keys = Object.keys(v);
    return "{" + keys.map(k => JSON.stringify(k) + ": " + ser(v[k])).join(", ") + "}";
  }
  return ser(obj);
}

function updateMap(file, opts) {
  const path = '/testbed/dist/css/' + file;
  const map = JSON.parse(fs.readFileSync(path, 'utf8'));
  let lines = decodeMappings(map.mappings);

  if (opts.deleteLines) {
    const [dStart, dEnd] = opts.deleteLines;
    lines = lines.slice(0, dStart).concat(lines.slice(dEnd + 1));
  }

  // source shifts
  if (opts.srcShifts) {
    lines = lines.map(ln => (ln || []).map(seg => {
      if (seg.src === undefined) return seg;
      const sh = opts.srcShifts.find(s => s.src === seg.src && seg.ol >= s.fromLine);
      if (sh) return { ...seg, ol: seg.ol + sh.delta };
      return seg;
    }));
  }

  // custom segment replacements: {genIndex: [segs...]}
  if (opts.setSegments) {
    for (const [k, segs] of Object.entries(opts.setSegments)) {
      lines[parseInt(k)] = segs;
    }
  }

  map.mappings = encodeMappings(lines);

  if (opts.sourcesContent) {
    for (const [idx, content] of Object.entries(opts.sourcesContent)) {
      map.sourcesContent[parseInt(idx)] = content;
    }
  }

  const out = byteExactSerialize(map) + '\n';
  fs.writeFileSync(path, out);
  console.log('updated', file, 'mapping lines', lines.length, 'bytes', out.length);
}

function buildNewRawCss() {
  // sourcesContent[0] for the two css maps = raw sass css with carousel edits applied
  const cur = JSON.parse(fs.readFileSync('/testbed/dist/css/bootstrap.css.map', 'utf8')).sourcesContent[0];
  const lines = cur.split('\n');
  // block at raw 0-based 6055..6062 (1-based 6056..6063)
  const blockStart = 6055;
  const L_prev = lines[6064];
  const L_next = lines[6068];
  function urlContent(line) { const a = line.indexOf('url("'); const b = line.indexOf('")', a); return line.slice(a + 4, b + 1); }
  const u1 = urlContent(L_prev), u2 = urlContent(L_next);
  const n1 = `  background-image: url(${u1}) /*rtl:url(${u2})*/;`;
  const n2 = `  background-image: url(${u2}) /*rtl:url(${u1})*/;`;
  const removed = lines.slice(0, blockStart)
    .concat(lines.slice(0, 0)) // marker
    .concat(lines.slice(blockStart + 8));
  const newLines = [];
  for (let i = 0; i < removed.length; i++) {
    // old index mapping: removed indices correspond to:
    // 0..6054 = original 0..6054 ; 6055.. = original 6063..
    const origIdx = i < blockStart ? i : i + 8;
    if (origIdx === 6064) newLines.push(n1);
    else if (origIdx === 6068) newLines.push(n2);
    else newLines.push(lines[origIdx]);
  }
  return newLines.join('\n');
}

function buildNewRawCss2() {
  // simpler: operate on original lines array directly
  const cur = JSON.parse(fs.readFileSync('/testbed/dist/css/bootstrap.css.map', 'utf8')).sourcesContent[0];
  const lines = cur.split('\n');
