  const u1 = urlContent(L_prev), u2 = urlContent(L_next);
  const n1 = `  background-image: url(${u1}) /*rtl:url(${u2})*/;`;
  const n2 = `  background-image: url(${u2}) /*rtl:url(${u1})*/;`;
  const removedBlock = lines.slice(blockStart, blockStart + 8).join('\n');
  let res = cur.replace(removedBlock + '\n', '');
  const oldP = lines[6064];
  const oldN = lines[6068];
  res = res.replace(oldP, n1);
  res = res.replace(oldN, n2);
  return res;
}

