function byteExactSerialize(obj) {
  function esc(s) {
    let out = "";
    for (let i = 0; i < s.length; i++) {
      const c = s.charCodeAt(i);
      if (c === 0x22) out += "\\\"";
      else if (c === 0x5c) out += "\\\\";
      else if (c === 0x08) out += "\\b";
      else if (c === 0x09) out += "\\t";
      else if (c === 0x0a) out += "\\n";
      else if (c === 0x0c) out += "\\f";
      else if (c === 0x0d) out += "\\r";
      else if (c < 0x20) out += "\\u" + c.toString(16).toLowerCase().padStart(4, "0");
      else if (c < 0x80) out += s[i];
      else out += "\\u" + c.toString(16).toLowerCase().padStart(4, "0");
    }
    return "\"" + out + "\"";
  }
  function ser(v) {
    if (v === null) return "null";
    const t = typeof v;
    if (t === "number") return String(v);
    if (t === "boolean") return String(v);
    if (t === "string") return esc(v);
    if (Array.isArray(v)) return "[" + v.map(ser).join(", ") + "]";
    const keys = Object.keys(v);
    return "{" + keys.map(k => JSON.stringify(k) + ": " + ser(v[k])).join(", ") + "}";
  }
  return ser(obj);
}

function updateMap(file, opts) {
  const path = '/testbed/dist/css/' + file;
  const map = JSON.parse(fs.readFileSync(path, 'utf8'));
  let lines = decodeMappings(map.mappings);

  if (opts.deleteLines) {
    const [dStart, dEnd] = opts.deleteLines;
    lines = lines.slice(0, dStart).concat(lines.slice(dEnd + 1));
  }

  // source shifts
  if (opts.srcShifts) {
    lines = lines.map(ln => (ln || []).map(seg => {
      if (seg.src === undefined) return seg;
      const sh = opts.srcShifts.find(s => s.src === seg.src && seg.ol >= s.fromLine);
      if (sh) return { ...seg, ol: seg.ol + sh.delta };
      return seg;
    }));
  }

  // custom segment replacements: {genIndex: [segs...]}
  if (opts.setSegments) {
    for (const [k, segs] of Object.entries(opts.setSegments)) {
      lines[parseInt(k)] = segs;
    }
  }

  map.mappings = encodeMappings(lines);

  if (opts.sourcesContent) {
    for (const [idx, content] of Object.entries(opts.sourcesContent)) {
      map.sourcesContent[parseInt(idx)] = content;
    }
  }

  const out = byteExactSerialize(map) + '\n';
  fs.writeFileSync(path, out);
  console.log('updated', file, 'mapping lines', lines.length, 'bytes', out.length);
