const CHARS = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";

function encodeVLQ(n) {
  let vlq = n < 0 ? ((-n) << 1) + 1 : (n << 1);
  let out = "";
  do {
    let digit = vlq & 31;
    vlq >>>= 5;
    if (vlq > 0) digit |= 32;
    out += CHARS[digit];
  } while (vlq > 0);
  return out;
}

// lines: array of arrays of segments {gc, src?, ol?, oc?, n?}
// Encode following the source-map spec: genCol resets per line; src/ol/oc/name carry across lines.
function encodeMappings(lines) {
  let out = "";
  let prevGenCol = 0;
  let prevSrc = 0, prevOl = 0, prevOc = 0, prevName = 0;
  for (let li = 0; li < lines.length; li++) {
    if (li > 0) out += ";";
    prevGenCol = 0;
    const segs = lines[li];
    for (let si = 0; si < segs.length; si++) {
      const seg = segs[si];
      if (si > 0) out += ",";
      const dgc = seg.gc - prevGenCol;
      out += encodeVLQ(dgc);
      prevGenCol = seg.gc;
      if (seg.src !== undefined) {
        out += encodeVLQ(seg.src - prevSrc);
        out += encodeVLQ(seg.ol - prevOl);
        out += encodeVLQ(seg.oc - prevOc);
        prevSrc = seg.src; prevOl = seg.ol; prevOc = seg.oc;
        if (seg.n !== undefined) {
          out += encodeVLQ(seg.n - prevName);
          prevName = seg.n;
        }
      }
    }
  }
  return out;
}

module.exports = { encodeMappings, encodeVLQ };

if (require.main === module) {
