const { decodeMappings } = require('/tmp/opencode/vlq.js');
const { encodeMappings } = require('/tmp/opencode/maptransform.js');
const fs = require('fs');

function byteExactSerialize(obj) {
  function esc(s) {
    let out = "";
    for (let i = 0; i < s.length; i++) {
      const c = s.charCodeAt(i);
      if (c === 0x22) out += "\\\"";
      else if (c === 0x5c) out += "\\\\";
      else if (c === 0x08) out += "\\b";
      else if (c === 0x09) out += "\\t";
      else if (c === 0x0a) out += "\\n";
      else if (c === 0x0c) out += "\\f";
      else if (c === 0x0d) out += "\\r";
      else if (c < 0x20) out += "\\u" + c.toString(16).toLowerCase().padStart(4, "0");
      else if (c < 0x80) out += s[i];
      else out += "\\u" + c.toString(16).toLowerCase().padStart(4, "0");
    }
    return "\"" + out + "\"";
  }
  function ser(v) {
    if (v === null) return "null";
    const t = typeof v;
    if (t === "number") return String(v);
    if (t === "boolean") return String(v);
    if (t === "string") return esc(v);
    if (Array.isArray(v)) return "[" + v.map(ser).join(", ") + "]";
    const keys = Object.keys(v);
    return "{" + keys.map(k => JSON.stringify(k) + ": " + ser(v[k])).join(", ") + "}";
  }
  return ser(obj);
}

const CSS_REMOVE = [
  "  --bs-accordion-btn-focus-border-color: #86b7fe;\n",
  "  border-color: var(--bs-accordion-btn-focus-border-color);\n",
];
const ACC_REMOVE = [
  "  --#{$prefix}accordion-btn-focus-border-color: #{$accordion-button-focus-border-color};\n",
  "    border-color: var(--#{$prefix}accordion-btn-focus-border-color);\n",
];
const VAR_OLD = "$accordion-button-focus-border-color:     $input-focus-border-color !default;";
const VAR_NEW = "// Deprecated in v5.3.3\n" + VAR_OLD;

const DEL_GEN = {
  "bootstrap.css.map": [4581, 4639],
  "bootstrap.rtl.css.map": [4579, 4637],
};

function accordionOlShift(ol) {
  if (ol >= 77) return ol - 2;      // 0-based lines after removed 76
  if (ol >= 23) return ol - 1;      // between removed 22 and 76
  return ol;
}
function sc0OlShift(ol) {
  if (ol >= 4552) return ol - 2;    // 0-based: removed lines 4494 & 4552
  if (ol >= 4494) return ol - 1;
  return ol;
}

function transformCssMap(base, varIdx) {
  const path = '/tmp/replay/' + base + '.css.map';
  const m = JSON.parse(fs.readFileSync(path, 'utf8'));
  const names = m.sources;
  const acc = names.indexOf('../../scss/_accordion.scss');
  const varI = names.indexOf('../../scss/_variables.scss');
  let lines = decodeMappings(m.mappings);

  // 1) delete generated lines (desc order)
  const dels = DEL_GEN[base + '.css.map'];
  for (const d of dels.slice().sort((a, b) => b - a)) {
    lines.splice(d, 1);
  }

  // 2) source-line shifts
  for (let li = 0; li < lines.length; li++) {
    const segs = lines[li];
    for (let i = 0; i < segs.length; i++) {
      const s = segs[i];
      if (s.src === undefined) continue;
      if (s.src === 0 && s.ol >= 4494) {
        segs[i] = { ...s, ol: sc0OlShift(s.ol) };
      } else if (s.src === acc && s.ol >= 23) {
        segs[i] = { ...s, ol: accordionOlShift(s.ol) };
      } else if (s.src === varI && s.ol >= 1385) {
        segs[i] = { ...s, ol: s.ol + 1 };
      }
    }
  }

  m.mappings = encodeMappings(lines);

  // 3) embedded contents
  if (acc >= 0) {
    let c = m.sourcesContent[acc];
    for (const old of ACC_REMOVE) {
      const n = c.split(old).length - 1;
      if (n !== 1) throw new Error(base + ' acc count ' + n);
      c = c.replace(old, '');
    }
    m.sourcesContent[acc] = c;
  }
  if (varI >= 0) {
    let c = m.sourcesContent[varI];
    if (!c.includes('Deprecated in v5.3.3')) {
      const n = c.split(VAR_OLD).length - 1;
      if (n !== 1) throw new Error(base + ' var count ' + n);
      c = c.replace(VAR_OLD, VAR_NEW);
      m.sourcesContent[varI] = c;
    }
  }
  let c0 = m.sourcesContent[0];
  for (const old of CSS_REMOVE) {
    const n = c0.split(old).length - 1;
    if (n !== 1) throw new Error(base + ' sc0 count ' + n);
    c0 = c0.replace(old, '');
  }
  m.sourcesContent[0] = c0;

  fs.writeFileSync(path, byteExactSerialize(m) + '\n');
  console.log('done', base, 'mapping lines', lines.length);
  return m;
}

function transformMinMap(base) {
  const path = '/tmp/replay/' + base + '.css.map';
  const m = JSON.parse(fs.readFileSync(path, 'utf8'));
  const acc = m.sources.indexOf('../../scss/_accordion.scss');
  let lines = decodeMappings(m.mappings);

  // gather removed-line marker gcs
  let startA = null, startB = null;
  for (let li = 0; li < lines.length; li++) {
    for (const s of (lines[li] || [])) {
      if (s.src === acc && s.ol === 22 && startA === null) startA = s.gc;
      if (s.src === acc && s.ol === 76 && startB === null) startB = s.gc;
    }
  }
  const lenA = "--bs-accordion-btn-focus-border-color:#86b7fe;".length;
  const lenB = "border-color:var(--bs-accordion-btn-focus-border-color);".length;
  const endA = startA + lenA;
  const endB = startB + lenB;
  if (startA === null || startB === null) throw new Error(base + ' marker missing');

  for (let li = 0; li < lines.length; li++) {
    const segs = lines[li];
    const out = [];
    for (const s of segs) {
      if (s.src === acc && (s.ol === 22 || s.ol === 76)) continue; // removed lines
      let ns = s;
      if (s.src === acc && s.ol >= 23) ns = { ...s, ol: accordionOlShift(s.ol) };
      // column shifts for any segment after removed text
      let dgc = 0;
      if (ns.gc >= endB) dgc = -(lenA + lenB);
      else if (ns.gc >= endA) dgc = -lenA;
      if (dgc) ns = { ...ns, gc: ns.gc + dgc };
      out.push(ns);
    }
    lines[li] = out;
  }

  m.mappings = encodeMappings(lines);
  if (acc >= 0) {
    let c = m.sourcesContent[acc];
    for (const old of ACC_REMOVE) {
      const n = c.split(old).length - 1;
      if (n !== 1) throw new Error(base + ' acc count ' + n);
      c = c.replace(old, '');
    }
    m.sourcesContent[acc] = c;
  }
  fs.writeFileSync(path, byteExactSerialize(m) + '\n');
  console.log('done', base, 'mapping lines', lines.length, 'startA', startA, 'startB', startB);
  return m;
}

const which = process.argv[2];
if (which === 'css') {
  transformCssMap('bootstrap', 6);
  transformCssMap('bootstrap.rtl', 6);
} else if (which === 'min') {
  transformMinMap('bootstrap.min');
  transformMinMap('bootstrap.rtl.min');
}

