      else if (c === 0x0d) out += "\\r";
      else if (c < 0x20) out += "\\u" + c.toString(16).toLowerCase().padStart(4, "0");
      else if (c < 0x80) out += s[i];
      else out += "\\u" + c.toString(16).toLowerCase().padStart(4, "0");
    }
    return "\"" + out + "\"";
  }
